import { test, expect } from '@playwright/test';

test.describe('403 Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display access denied page when API returns 403 status', async ({ page }) => {
    // Setup intercept for API call
    await page.route('**/api/user/profile', (route) => {
      route.abort('failed');
    });

    // Attempt to access a protected route
    const profileButton = page.getByRole('button', { name: /profile/i });
    await profileButton.click();

    // Verify access denied page is displayed
    const accessDeniedMessage = page.getByText(/access denied/i);
    await expect(accessDeniedMessage).toBeVisible();

    // Verify error status is displayed
    const errorStatus = page.getByText(/403 Forbidden/i);
    await expect(errorStatus).toBeVisible();

    // Verify navigation is blocked
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).not.toBeVisible();

    // Verify user is not logged in
    const userName = page.getByText(/user name/i);
    await expect(userName).not.toBeVisible();

    // Verify error page has proper title
    const errorPageTitle = page.getByText(/access denied/i);
    await expect(errorPageTitle).toBeVisible();
  });

  test('should handle 403 error with custom error page', async ({ page }) => {
    // Setup intercept for API call
    await page.route('**/api/user/profile', (route) => {
      route.abort('failed');
    });

    // Setup intercept for custom error page
    await page.route('**/error/403', (route) => {
      route.continue();
    });

    // Attempt to access a protected route
    const profileButton = page.getByRole('button', { name: /profile/i });
    await profileButton.click();

    // Verify custom error page is displayed
    const errorPageTitle = page.getByText(/custom error/i);
    await expect(errorPageTitle).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/access denied/i);
    await expect(errorMessage).toBeVisible();

    // Verify navigation is blocked
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).not.toBeVisible();

    // Verify user is not logged in
    const userName = page.getByText(/user name/i);
    await expect(userName).not.toBeVisible();

    // Verify error page has proper title
    await expect(errorPageTitle).toBeVisible();
  });
});
